using System;
using System.Linq;
using System.Windows;
partial class ConanPet {
 int appliedMonitorInterval;
 readonly System.Collections.Generic.Dictionary<string,TaskbarMonitor> taskbarMirrors=new System.Collections.Generic.Dictionary<string,TaskbarMonitor>();TaskbarMonitor cardAnchorSource;
 TaskbarMonitor CreateTaskbarView(){var view=new TaskbarMonitor();view.OpenCard+=()=>{cardAnchorSource=view;OpenTaskbarMonitorCard();};view.OpenQuota+=()=>{OpenTerminal();terminal.ShowQuotaPage();};view.PositionChanged+=()=>{try{lock(assistant)assistant.Save();}catch(System.IO.IOException ex){Say("任务栏位置保存失败："+ex.Message);}catch(UnauthorizedAccessException ex){Say("任务栏位置无法保存："+ex.Message);}};view.OpenAppearance+=()=>{OpenTerminal();terminal.ShowPage("任务栏外观");};view.Disable+=()=>{lock(assistant){assistant.Config.Monitor.Taskbar=false;assistant.Save();}RefreshMonitorWindows();};return view;}
 void ConfigureTaskbarViews(){var cfg=assistant.Config.Monitor;var targets=TaskbarScreens.Targets(cfg.TaskbarAllScreens,cfg.TaskbarScreen,System.Windows.Forms.Screen.PrimaryScreen.DeviceName,System.Windows.Forms.Screen.AllScreens.Select(s=>s.DeviceName));taskbarMonitor.ScreenOverride=cfg.TaskbarAllScreens?targets[0]:null;var mirrors=cfg.Taskbar&&cfg.TaskbarAllScreens?targets.Skip(1).ToArray():new string[0];foreach(var key in taskbarMirrors.Keys.Where(k=>!mirrors.Contains(k)).ToArray()){var removed=taskbarMirrors[key];if(cardAnchorSource==removed){cardAnchorSource=null;if(monitorCard!=null)monitorCard.TaskbarAnchor=null;}removed.Dispose();taskbarMirrors.Remove(key);}foreach(string key in mirrors)if(!taskbarMirrors.ContainsKey(key)){var view=CreateTaskbarView();view.ScreenOverride=key;taskbarMirrors[key]=view;view.Update(assistantSnapshot==null?null:assistantSnapshot.Sample,cfg);}}
 string TaskbarViewsStatus(){return taskbarMonitor==null?"尚未初始化":taskbarMirrors.Count==0?taskbarMonitor.Status:"多屏同步 · "+(taskbarMirrors.Count+1)+" 个窗口\n"+taskbarMonitor.Status+"\n"+String.Join("\n",taskbarMirrors.Values.Select(v=>v.Status));}
 void DisposeTaskbarViews(){foreach(var view in taskbarMirrors.Values)view.Dispose();taskbarMirrors.Clear();if(taskbarMonitor!=null)taskbarMonitor.Dispose();cardAnchorSource=null;}
 void ClearMonitorSamples(){if(taskbarMonitor!=null)taskbarMonitor.Update(null,assistant.Config.Monitor);foreach(var view in taskbarMirrors.Values)view.Update(null,assistant.Config.Monitor);if(monitorCard!=null)monitorCard.Update(null);}
 void InitializeMonitorWindows(){taskbarMonitor=CreateTaskbarView();monitorPositionTimer.Interval=TimeSpan.FromSeconds(1);monitorPositionTimer.Tick+=(s,e)=>{ConfigureTaskbarViews();taskbarMonitor.Position();foreach(var view in taskbarMirrors.Values)view.Position();if(monitorCard!=null){if(cardAnchorSource!=null&&!cardAnchorSource.IsDisposed)monitorCard.TaskbarAnchor=cardAnchorSource.Bounds;monitorCard.Near(this);}};monitorPositionTimer.Start();}
 void RefreshMonitorWindows(){if(!assistant.Config.Bubbles){messages.Clear();bubble.Hide();}int interval=Math.Max(500,Math.Min(5000,assistant.Config.Monitor.RefreshMilliseconds));if(assistantTimer!=null&&appliedMonitorInterval!=interval){appliedMonitorInterval=interval;assistantTimer.Change(interval,interval);}if(taskbarMonitor!=null){ConfigureTaskbarViews();taskbarMonitor.Update(assistantSnapshot==null?null:assistantSnapshot.Sample,assistant.Config.Monitor);foreach(var view in taskbarMirrors.Values)view.Update(assistantSnapshot==null?null:assistantSnapshot.Sample,assistant.Config.Monitor);}if(monitorCard!=null)monitorCard.Update(assistantSnapshot==null?null:assistantSnapshot.Sample);}
 void OpenMonitorCard(){cardAnchorSource=null;ShowMonitorCard(false);}
 void OpenTaskbarMonitorCard(){ShowMonitorCard(true);}
 void ShowMonitorCard(bool fromTaskbar){var card=monitorCard;if(card==null){card=new MonitorCard(assistant.Config.Monitor,()=>{lock(assistant)assistant.Save();}){Owner=this};monitorCard=card;card.OpenSettings+=()=>{OpenTerminal();terminal.ShowPage("监控与预警");};card.Closed+=(s,e)=>{if(Object.ReferenceEquals(monitorCard,card))monitorCard=null;};}card.TaskbarAnchor=fromTaskbar?(System.Drawing.Rectangle?)(cardAnchorSource??taskbarMonitor).Bounds:null;card.Update(assistantSnapshot==null?null:assistantSnapshot.Sample);card.Near(this);card.Show();if(card.IsVisible){card.Near(this);card.Activate();}}
}
